(5, '2026-06-24 08:34:11', '::1', 'benaminmed@gmail.com', 'Globuild Devis - Demande de Test Name', 'Vous avez reçu une nouvelle demande de devis personnalisé :\n\nNom: Test Name\nE-mail: test@example.com\nTéléphone: 0600000000\nService demandé: Ingénierie Civile (BTP)\n\nNote/Description du projet:\nThis is a test message for devis.\n\n---\nCet e-mail a été envoyé depuis le formulaire de devis de Globuild.', 'From: Test Name <wordpress@localhost>,\\nX-WPCF7-Content-Type: text/plain,\\nReply-To: test@example.com,\\nContent-Type: text/html', '', NULL, '1.16.0'),
(6, '2026-06-24 08:36:39', '::1', 'benaminmed@gmail.com', 'Globuild Contact - Test Subject', 'Vous avez reçu un nouveau message via le formulaire de contact :\n\nNom: Contact Test Name\nE-mail: contact_test@example.com\nSujet: Test Subject\n\nMessage:\nThis is a test message for contact.\n\n---\nCet e-mail a été envoyé depuis le formulaire de contact de Globuild.', 'From: Contact Test Name <wordpress@localhost>,\\nX-WPCF7-Content-Type: text/plain,\\nReply-To: contact_test@example.com,\\nContent-Type: text/html', '', NULL, '1.16.0'),
(7, '2026-06-24 09:17:36', '::1', 'benaminmed@gmail.com', 'Globuild Devis - Demande de Test Name', 'Vous avez reçu une nouvelle demande de devis personnalisé :\n\nNom: Test Name\nE-mail: test@example.com\nTéléphone: 0600000000\nService demandé: Solutions Numériques (IT)\n\nNote/Description du projet:\nok\n\n---\nCet e-mail a été envoyé depuis le formulaire de devis de Globuild.', 'From: Test Name <wordpress@localhost>,\\nX-WPCF7-Content-Type: text/plain,\\nReply-To: test@example.com,\\nContent-Type: text/html', '', NULL, '1.16.0'),
(8, '2026-06-24 11:59:02', '::1', 'benaminmed@gmail.com', 'Globuild Devis - Demande de ben', 'Vous avez reçu une nouvelle demande de devis personnalisé :\n\nNom: ben\nE-mail: benaminmedr@gmail.com\nTéléphone: 0600000\nService demandé: Sélectionner un Service\n\nNote/Description du projet:\nvf\n\n---\nCet e-mail a été envoyé depuis le formulaire de devis de Globuild.', 'From: ben <wordpress@localhost>,\\nX-WPCF7-Content-Type: text/plain,\\nReply-To: benaminmedr@gmail.com,\\nContent-Type: text/html', '', 'Invalid address:  (From): wordpress@localhost', '1.16.0'),
(9, '2026-06-24 11:59:33', '::1', 'benaminmed@gmail.com', 'Globuild Devis - Demande de ben', 'Vous avez reçu une nouvelle demande de devis personnalisé :\n\nNom: ben\nE-mail: benaminmedr@gmail.com\nTéléphone: 0608212200\nService demandé: Sélectionner un Service\n\nNote/Description du projet:\nvf\n\n---\nCet e-mail a été envoyé depuis le formulaire de devis de Globuild.', 'From: ben <wordpress@localhost>,\\nX-WPCF7-Content-Type: text/plain,\\nReply-To: benaminmedr@gmail.com,\\nContent-Type: text/html', '', 'Invalid address:  (From): wordpress@localhost', '1.16.0'),
(10, '2026-07-17 16:31:20', '::1', 'benaminmed@gmail.com', '[Globuild] Votre site a été mis à jour vers WordPress 7.0.1', 'Bonjour ! Votre site à l’adresse http://localhost/gloservices a été automatiquement mis à jour vers WordPress 7.0.1.\n\nVous n’avez rien de plus à faire. Pour en savoir plus sur la version 7.0.1, lisez l’écran À Propos de WordPress : \nhttp://localhost/gloservices/wp-admin/about.php\n\nSi vous rencontrez des problèmes ou avez besoin d’assistance, les volontaires du forum d’entraide de WPFR (https://wpfr.net/support) devraient pouvoir vous aider.\nhttps://wpfr.net/support\n\nL’équipe WordPress\n', 'Content-Type: text/html', '', NULL, '1.16.0'),
(11, '2026-07-20 11:36:44', '::1', 'benaminmed@gmail.com', '[Globuild] Votre site a été mis à jour vers WordPress 7.0.2', 'Bonjour ! Votre site à l’adresse http://localhost/gloservices a été automatiquement mis à jour vers WordPress 7.0.2.\n\nVous n’avez rien de plus à faire. Pour en savoir plus sur la version 7.0.2, lisez l’écran À Propos de WordPress : \nhttp://localhost/gloservices/wp-admin/about.php\n\nSi vous rencontrez des problèmes ou avez besoin d’assistance, les volontaires du forum d’entraide de WPFR (https://wpfr.net/support) devraient pouvoir vous aider.\nhttps://wpfr.net/support\n\nL’équipe WordPress\n', 'Content-Type: text/html', '', NULL, '1.16.0'),
(12, '2026-07-21 09:17:25', '::1', 'benaminmed@gmail.com', '[Globuild] Réinitialisation du mot de passe', 'Quelqu’un a demandé la réinitialisation du mot de passe pour le compte suivant :\r\n\r\nTitre du site : Globuild\r\n\r\nIdentifiant : Globuild\r\n\r\nSi ceci est une erreur, ignorez cet e-mail et rien ne se passera.\r\n\r\nPour renouveler votre mot de passe, cliquez sur le lien suivant :\r\n\r\nhttp://localhost/gloservices/wp-login.php?login=Globuild&key=ZNHxgk4SYGCg7xYomC6u&action=rp&wp_lang=fr_FR\r\n\r\nCette demande de réinitialisation de mot de passe provient de l’adresse IP ::1.\r\n', 'Content-Type: text/html', '', NULL, '1.16.0'),
(13, '2026-07-21 09:19:19', '::1', 'benaminmed@gmail.com', '[Globuild] Réinitialisation du mot de passe', 'Quelqu’un a demandé la réinitialisation du mot de passe pour le compte suivant :\r\n\r\nTitre du site : Globuild\r\n\r\nIdentifiant : Globuild\r\n\r\nSi ceci est une erreur, ignorez cet e-mail et rien ne se passera.\r\n\r\nPour renouveler votre mot de passe, cliquez sur le lien suivant :\r\n\r\nhttp://localhost/gloservices/wp-login.php?login=Globuild&key=I2ayfqK45aYGxZAPGUTl&action=rp&wp_lang=fr_FR\r\n\r\nCette demande de réinitialisation de mot de passe provient de l’adresse IP ::1.\r\n', 'Content-Type: text/html', '', NULL, '1.16.0'),
(14, '2026-07-21 09:54:59', '::1', 'benaminmed@gmail.com', '[Globuild] Mot de passe changé', 'Bonjour Globuild,\n\nCe message vous confirme que votre mot de passe a bien été modifié sur Globuild.\n\nSi vous n’avez pas modifié votre mot de passe, veuillez contacter l’administrateur ou l’administratrice du site à cette adresse :\nbenaminmed@gmail.com\n\nCe message a été envoyé à benaminmed@gmail.com\n\nCordialement,\nL’équipe de Globuild\nhttp://localhost/gloservices', 'Content-Type: text/html', '', NULL, '1.16.0'),
(15, '2026-07-21 09:55:35', '::1', 'benaminmed@gmail.com', '[Globuild] Mot de passe changé', 'Bonjour Globuild,\n\nCe message vous confirme que votre mot de passe a bien été modifié sur Globuild.\n\nSi vous n’avez pas modifié votre mot de passe, veuillez contacter l’administrateur ou l’administratrice du site à cette adresse :\nbenaminmed@gmail.com\n\nCe message a été envoyé à benaminmed@gmail.com\n\nCordialement,\nL’équipe de Globuild\nhttp://localhost/gloservices', 'Content-Type: text/html', '', NULL, '1.16.0');
